//! The engine's system index definitions (`src/jrd/idx.h`), every
//! macro resolved to its value. Generated by `qa/gen-catalog-init.py`;
//! do not edit by hand. Content pinned against a fresh engine file's
//! RDB$INDICES / RDB$INDEX_SEGMENTS rows in `tests/catalog_index.rs`.

/// One index segment: its RDB$INDEX_SEGMENTS field name and key type
/// (`idx_numeric` 0, `idx_string` 1, `idx_metadata` 4,
/// `idx_timestamp_tz` 12; btr.h:123-135).
pub struct SysIndexSeg {
    pub field: &'static str,
    pub itype: u8,
}

/// A system index: its `RDB$INDEX_n` id, relation, flags, the
/// stored segment count - which wins over the table when they
/// disagree (`RDB$INDEX_84` lists 3, stores 2) - and every listed
/// segment in order.
pub struct SysIndex {
    pub id: u8,
    pub relation: &'static str,
    pub unique: bool,
    pub descending: bool,
    pub count: u8,
    pub segments: &'static [SysIndexSeg],
}

